-- ov3-harness-07-census-2-plan.commit.sql
--
-- ============================== COMMIT - THIS INSTALLS ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement:
-- COMMIT TRANSACTION here, ROLLBACK TRANSACTION there. Run the preflight first.
--
-- WHAT THIS ADDS: the plan of flight ov3-harness-census-2 (work class owner-objective: clears on the deterministic review alone), the
-- evidence.flight_plan row of planner id claude-code-opus-5-5-ov3-harness-census-2, through the installed writer evidence.upsert_flight_plan.
-- WHERE: the sfx-identity database. GUARD: the writer has its four parameters and the owner principal is active.
-- RESULT SETS: guard; plans (plan_revision 1, matches_reviewed_file 1).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @params int=(SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'evidence.upsert_flight_plan') AND name IN (N'@principal_id',N'@agent_id',N'@objective',N'@steps_json'));
DECLARE @active int=(SELECT COUNT(*) FROM [identity].principal WHERE principal_id='565de6d4-ebcd-408b-9359-04d21dc62183' AND active=1);
SELECT N'guard' AS result_set,@params AS writer_parameters,4 AS expected_parameters,@active AS owner_principal_active;
IF @params<>4 OR @active<>1
BEGIN
 RAISERROR(N'OV3_HARNESS_PLAN_GUARD: the plan writer or the owner principal is not as reviewed; nothing was recorded.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
DECLARE @p uniqueidentifier='565de6d4-ebcd-408b-9359-04d21dc62183';
DECLARE @r TABLE(plan_revision bigint,plan_digest binary(32),updated_at datetime2(7));
INSERT @r EXEC evidence.upsert_flight_plan @principal_id=@p,@agent_id=N'claude-code-opus-5-5-ov3-harness-census-2',@objective=N'Write the capability-area census of the complete agentic harness, check it against every recorded obligation for both ownership and fulfillment, correct what the checks find, and retain and deliver it, as the owner''s objective, with no owner approval or decision.',
 @steps_json=N'[{"stepId":"plan-header","contractId":"estate-flight-plan.v1","promiseId":"ov3-harness-census-2","flightType":"execution","workClass":"owner-objective","unknowns":[]},{"stepId":"track-ownership","capabilityId":"apply-declared-change","historicalBasis":"project-tracking PASSED in plans 358 to 440 and in flights ov3-harness-scope and ov3-harness-census (track steps; the census flight recorded the supersession of task oah-scope as its statusDescription)","input":{"contractId":"declared-change.v1","changeKind":"project-tracking","payload":{"contractId":"project-tracking-change.v1","project":{"projectId":"ov3-complete-agentic-harness","agentUserStory":"As the OV3 network, I take the owner''s objective and own the work: I write my own census and canonical features as a complete agentic harness from the owner''s recorded directions and my declared state, check them against every recorded obligation for both ownership and fulfillment, correct the gaps I can resolve, and plan and build my own future state, so that my design is durable authority in the estate and the owner decides only what they reserve.","acceptanceCriteria":"The census and one canonical feature per census area are written by OV3 from the retained specification, checked against every recorded obligation for both ownership and fulfillment, and corrected by OV3 before they are retained and delivered; OV3 asks the owner only for decisions the owner reserves and never records an owner decision the owner did not make; every later build task names the feature it implements; each built capability declares its feature as canonical; no stance that contradicts the owner direction remains unsuperseded; one objective sent once is planned, flown, corrected and closed by OV3 with no further command (task oah-agency-acceptance)."},"tasks":[{"projectTaskId":"oah-census","capabilityRef":"ask-model + analysis.check_capability_census + analysis.check_census_fulfillment (performs); fulfillment gate CENSUS_READY with every obligation fulfilled (verifies)","statusDescription":"Carried by flight ov3-harness-census-2, which supersedes flight ov3-harness-census under OV3''s own authority (work class owner-objective, owner-direction revision 2). Flight ov3-harness-census is not flown again; its decision point ov3-complete-agentic-harness/census stays unanswered, and no owner decision is recorded for it.","requiredOutcome":"ask-model writes the census of the complete agentic harness from specification:ov3-complete-agentic-harness; analysis.check_capability_census checks that every recorded obligation (each tracker project, each task of this project, each owner direction) is answered; a separate ask-model pass judges whether each area''s responsibility does what each obligation it claims requires, and analysis.check_census_fulfillment counts an obligation as owned only when a claiming area fulfills it; OV3 corrects every defect both checks find; the checked census is retained as capability-census:ov3-complete-agentic-harness and delivered, with no owner approval or decision."},{"projectTaskId":"oah-features","requiredOutcome":"design-feature-gherkin writes one complete @-annotated feature per area of the checked census (capability-census:ov3-complete-agentic-harness); each is checked, retained as harness-feature:<capabilityId> and delivered, with no owner approval or decision."},{"projectTaskId":"oah-census-capability","requiredOutcome":"Once flight ov3-harness-census-2 reads PROMISE_CLOSED, its steps become a declared capability that turns any retained specification into a census checked against every recorded obligation for both ownership and fulfillment, binding analysis.read_capability_census_sources, analysis.check_capability_census and analysis.check_census_fulfillment and correcting what the checks find; proven by one run reading PROMISE_CLOSED."},{"projectTaskId":"oah-owner-objective-clearance","description":"OV3 fulfills the owner''s objectives without asking for approval","status":"OPEN","requiredOutcome":"Plans that fulfill an objective the owner gave carry work class owner-objective and clear on the deterministic review alone (flight-clearance-policy:owner-objective); OV3 asks the owner only for the decisions the owner reserves.","capabilityRef":"owner SQL ov3-harness-06 (performs); resolve-flight-clearance CLEARED on OV3_CONFORMANT alone for flight ov3-harness-census-2 (verifies)","dependencyRefs":"","assignedActor":"SFX Objective Agent","md":"Owner direction 2026-11-02 (owner-direction:ov3-complete-agentic-harness, revision 2); specification:ov3-complete-agentic-harness sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09."},{"projectTaskId":"oah-provider-bindings","description":"Every provider-dependent feature names its verified provider binding","status":"OPEN","requiredOutcome":"Every canonical feature whose scenario depends on a provider names the declared provider capability OV3 needs by its estate identity, the result it must produce there, and the run evidence that proves it did so; a provider OV3 only expects stays a candidate until OV3 verifies it, and OV3 discovers, proves and maintains those bindings. Census-2 is the first: each of its model calls must honor MODEL_SELECTION, proved by its receipt.","capabilityRef":"design-feature-gherkin + analysis.verify_model_binding (performs); BINDING_HONORED in flight ov3-harness-census-2 and a provider binding in every provider-dependent feature (verifies)","dependencyRefs":"oah-features","assignedActor":"SFX Objective Agent","md":"Owner direction 2026-11-02, endorsing the provider-binding recommendation (owner-direction revision 2)."},{"projectTaskId":"oah-agency-acceptance","description":"Transfer of agency: one objective, sent once, closes with no further command","status":"OPEN","requiredOutcome":"The owner sends one objective, once. OV3 plans and flies it, catches a result that misses the owner''s intent (for example one area, format-labels, \"Alphabetize display labels\", claiming every obligation), corrects it, and delivers evidence of closure, with no further command from the owner or another agent.","capabilityRef":"OV3 planning, review, flight and closure (performs); one objective run reading PROMISE_CLOSED with no command after the objective (verifies)","dependencyRefs":"oah-census","assignedActor":"SFX Objective Agent","md":"Acceptance test from the review the owner endorsed on 2026-11-02 (\"Here''s the review that will align us\"); the id-only census check passed format-labels in run 15e76f2e."}],"verificationCapabilityId":"read-project-tracker","preflight":{"input":{"payload":{"projectId":"ov3-complete-agentic-harness"}},"expected":{"disposition":"terminated"}},"route":{"resolvedDisposition":"terminated"}}},"obligationIds":["O1"],"expect":{"path":"$.disposition","equals":"COMMITTED"}},{"stepId":"read-sources","capabilityId":"sql-database-reader","historicalBasis":"sources ce4cf538 read 52 live (39 projects, 10 tasks, the 3 lines of direction revision 1); the flight reads them after SQL 06 adds revision 2 (17 lines) and after its own tracker step adds tasks oah-owner-objective-clearance, oah-provider-bindings and oah-agency-acceptance: 69 on the 2026-11-02 baseline; the procedure body is the probed statement","input":{"dataSource":"sfx-estate-database","statement":"EXEC analysis.read_capability_census_sources @input=@input;","resultColumn":"value","input":{"specDigest":"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09","projectId":"ov3-complete-agentic-harness","ownerDirectionKind":"owner-direction:ov3-complete-agentic-harness"}},"obligationIds":["O2"],"expect":{"path":"$.value.found","equals":1}},{"stepId":"write-census","capabilityId":"ask-model","historicalBasis":"probe bc12cf9e: MODEL_RESPONSE_OBTAINED (deepseek/deepseek-flash, 26 s, 30 areas) on the population the flight reads: 69 = 39 projects, 13 tasks (its tracker step applied), 17 direction lines","input":{"requestId":"ov3-harness-census-write","modelRequest":{"interaction":{"messages":[{"role":"system","content":"You decompose the product a specification describes into capability areas for the SideFX estate, where every capability is declared data and holds exactly one canonical feature. The product is OV3 itself: the agentic harness that takes an objective and owns the work - assembling evidence, planning, coordinating specialists, executing, checking results against the owner''s intent, correcting gaps, and building and improving itself. The recorded projects are evidence of what the harness must do and of the work it has run; a project''s own domain (for example financial analysis, resume documents or infrastructure) is not a harness area, but the harness need that the project reveals is. The first user message is the specification. The second lists the installed capability ids. The third is a JSON array of the recorded obligations, each with an id and its text: every tracker project, every task of the project, and every owner direction. Return one JSON object: product (the product name) and areas, at most 30. Each area is one capability the harness needs, named by a proposed capability id (lowercase ASCII letters, digits, dots and hyphens; unique), with its name (a few words), its responsibility (what it does and what it guarantees, at most 300 characters), covers (which of elaborate-planning, self-improvement, multi-agent-consensus, control-plane, deterministic-multi-step-execution and other the area serves), answers (the ids of the obligations from the third message this area is responsible for; at least one), and existingCapabilities (installed capability ids from the second message that the area extends or reuses; empty when none or when unsure). Every obligation in the third message must be answered by at least one area. Each of elaborate-planning, self-improvement, multi-agent-consensus, control-plane and deterministic-multi-step-execution must be covered by at least one area. Use only the given material. Cite only ids that appear verbatim in the second and third messages; never invent an obligation or capability id."},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"}]},"responsePolicy":{"format":"json","schema":{"type":"object","additionalProperties":false,"required":["product","areas"],"properties":{"product":{"type":"string"},"areas":{"type":"array","minItems":1,"maxItems":30,"items":{"type":"object","additionalProperties":false,"required":["capabilityId","name","responsibility","covers","answers","existingCapabilities"],"properties":{"capabilityId":{"type":"string","pattern":"^[a-z0-9][a-z0-9.-]*$"},"name":{"type":"string"},"responsibility":{"type":"string","maxLength":300},"covers":{"type":"array","items":{"type":"string","enum":["elaborate-planning","self-improvement","multi-agent-consensus","control-plane","deterministic-multi-step-execution","other"]}},"answers":{"type":"array","minItems":1,"items":{"type":"string"}},"existingCapabilities":{"type":"array","items":{"type":"string"}}}}}}},"maximumOutputTokens":12000,"temperature":0.2}}},"bind":[{"target":"modelRequest.interaction.messages[1].content","fromStep":"read-sources","path":"$.value.text"},{"target":"modelRequest.interaction.messages[2].content","fromStep":"read-sources","path":"$.value.capabilityIds"},{"target":"modelRequest.interaction.messages[3].content","fromStep":"read-sources","path":"$.value.obligations"}],"obligationIds":["O3"],"expect":{"path":"$.disposition","equals":"MODEL_RESPONSE_OBTAINED"}},{"stepId":"check-written","capabilityId":"sql-database-reader","historicalBasis":"probe bc00f99c: ran (CENSUS_INVALID: owner:1 unanswered, two invented citations removed)","input":{"dataSource":"sfx-estate-database","statement":"EXEC analysis.check_capability_census @input=@input;","resultColumn":"value","input":{"censusText":"(bound)","obligationsText":"(bound)","requiredCoverage":"elaborate-planning,self-improvement,multi-agent-consensus,control-plane,deterministic-multi-step-execution","specDigest":"sha256:a344104861ea0cb7e9557cc9b359a9e9567f7f3e921477d0cd596de0a6413c09","maxAreas":60}},"bind":[{"target":"input.censusText","fromStep":"write-census","path":"$.response.text"},{"target":"input.obligationsText","fromStep":"read-sources","path":"$.value.obligations"}],"obligationIds":["O3"],"expect":{"path":"$.value.ran","equals":1}},{"stepId":"judge-written","capabilityId":"ask-model","historicalBasis":"probe 8ab74de3: MODEL_RESPONSE_OBTAINED, 69 verdicts; for the review case format-labels, probe edd7f58e judged 0 of 69 fulfilled","input":{"requestId":"ov3-harness-census-judge","modelRequest":{"interaction":{"messages":[{"role":"system","content":"You check a capability-area census of OV3, the agentic harness that takes an objective and owns the work: assembling evidence, planning, coordinating specialists, executing, checking results against the owner''s intent, correcting gaps, and building and improving itself. The first user message is a JSON array of the recorded obligations, each with an id and its text. The second is the census: its areas, each with a capabilityId, a name, a responsibility, and answers (the obligation ids the area claims). For every obligation, decide which of the areas that claim it fulfill it. An area fulfills an obligation only when its name and responsibility, read literally, describe work that does what the obligation requires. Claiming the id is not enough, and neither is a covers label, a generic responsibility or a shared topic word. A tracker project obligation names work the harness ran or must run; an area fulfills it when its responsibility provides the harness capability that work needs, for example declaring, building and running the project''s domain capabilities from its specification. An area that does a project''s domain work itself, for example writing resume documents, analysing financial markets or provisioning infrastructure, is not a harness area and fulfills nothing. Return one JSON object with verdicts: one per obligation in the first message, in its order, each with obligationId, fulfilledBy (the capabilityIds of claiming areas that fulfill it; empty when none does) and reason (one short sentence: what the fulfilling area does that meets the obligation, or why no claiming area does). Never name an area that does not claim the obligation."},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"}]},"responsePolicy":{"format":"json","schema":{"type":"object","additionalProperties":false,"required":["verdicts"],"properties":{"verdicts":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["obligationId","fulfilledBy","reason"],"properties":{"obligationId":{"type":"string"},"fulfilledBy":{"type":"array","items":{"type":"string"}},"reason":{"type":"string","maxLength":200}}}}}},"maximumOutputTokens":12000,"temperature":0}}},"bind":[{"target":"modelRequest.interaction.messages[1].content","fromStep":"read-sources","path":"$.value.obligations"},{"target":"modelRequest.interaction.messages[2].content","fromStep":"check-written","path":"$.value.censusJson"}],"obligationIds":["O3"],"expect":{"path":"$.disposition","equals":"MODEL_RESPONSE_OBTAINED"}},{"stepId":"gate-written","capabilityId":"sql-database-reader","historicalBasis":"probe 8fde4890: ran (CENSUS_INVALID, 68 of 69 fulfilled); format-labels: the id check passed it (f11d0688) and this gate failed it, 0 of 69 fulfilled (6d20bf47)","input":{"dataSource":"sfx-estate-database","statement":"EXEC analysis.check_census_fulfillment @input=@input;","resultColumn":"value","input":{"censusText":"(bound)","obligationsText":"(bound)","judgmentText":"(bound)","idStatus":"(bound)","idFeedback":"(bound)"}},"bind":[{"target":"input.censusText","fromStep":"check-written","path":"$.value.censusJson"},{"target":"input.obligationsText","fromStep":"read-sources","path":"$.value.obligations"},{"target":"input.judgmentText","fromStep":"judge-written","path":"$.response.text"},{"target":"input.idStatus","fromStep":"check-written","path":"$.value.status"},{"target":"input.idFeedback","fromStep":"check-written","path":"$.value.feedback"}],"obligationIds":["O3"],"expect":{"path":"$.value.ran","equals":1}},{"stepId":"correct-census","capabilityId":"ask-model","historicalBasis":"probe 1f7cee92: MODEL_RESPONSE_OBTAINED, a patch replacing 4 areas; format-labels c2ebb6f8 (remove 1, add 30). A whole-census correction came back unchanged (741e3b44), so the pass returns a patch","input":{"requestId":"ov3-harness-census-correct","modelRequest":{"interaction":{"messages":[{"role":"system","content":"You decompose the product a specification describes into capability areas for the SideFX estate, where every capability is declared data and holds exactly one canonical feature. The product is OV3 itself: the agentic harness that takes an objective and owns the work - assembling evidence, planning, coordinating specialists, executing, checking results against the owner''s intent, correcting gaps, and building and improving itself. The recorded projects are evidence of what the harness must do and of the work it has run; a project''s own domain (for example financial analysis, resume documents or infrastructure) is not a harness area, but the harness need that the project reveals is. The first user message is the specification. The second lists the installed capability ids. The third is a JSON array of the recorded obligations, each with an id and its text: every tracker project, every task of the project, and every owner direction. Aim for at most 30 areas; the census must never exceed 60. Each area is one capability the harness needs, named by a proposed capability id (lowercase ASCII letters, digits, dots and hyphens; unique), with its name (a few words), its responsibility (what it does and what it guarantees, at most 300 characters), covers (which of elaborate-planning, self-improvement, multi-agent-consensus, control-plane, deterministic-multi-step-execution and other the area serves), answers (the ids of the obligations from the third message this area is responsible for; at least one), and existingCapabilities (installed capability ids from the second message that the area extends or reuses; empty when none or when unsure). Every obligation in the third message must be answered by at least one area. Each of elaborate-planning, self-improvement, multi-agent-consensus, control-plane and deterministic-multi-step-execution must be covered by at least one area. Use only the given material. Cite only ids that appear verbatim in the second and third messages; never invent an obligation or capability id. The fourth user message is the current census and the fifth lists its defects, found by two checks against the obligations: a deterministic check that every obligation id is answered, and a separate fulfillment check that judged whether each area''s name and responsibility actually do what each obligation it claims requires. Return one JSON object with only the changes that fix every listed defect: areas, each a complete area that replaces the area with the same capabilityId or is added, and remove, the capabilityIds of areas to delete. Areas you do not list stay as they are. Every unfulfilled obligation must end up answered by an area whose responsibility does what it requires: extend a fitting area''s responsibility and answers, or add an area. A rejected claim must not remain: replace the area without it, or rewrite the area so that it fulfills it. A project whose own domain is not a harness area (for example resume documents, financial analysis, infrastructure or publishing) is answered by the harness area that provides what its work needs, such as declaring, building and running domain capabilities from a specification, never by an area that does the domain work itself. When the census would exceed 60 areas, merge: remove areas and replace another so that its responsibility and answers cover theirs. If the fifth message says No defects., return empty areas and remove."},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"},{"role":"user","content":"(bound)"}]},"responsePolicy":{"format":"json","schema":{"type":"object","additionalProperties":false,"required":["areas","remove"],"properties":{"areas":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["capabilityId","name","responsibility","covers","answers","existingCapabilities"],"properties":{"capabilityId":{"type":"string","pattern":"^[a-z0-9][a-z0-9.-]*$"},"name":{"type":"string"},"responsibility":{"type":"string","maxLength":300},"covers":{"type":"array","items":{"type":"string","enum":["elaborate-planning","self-improvement","multi-agent-consensus","control-plane","deterministic-multi-step-execution","other"]}},"answers":{"type":"array","minItems":1,"items":{"type":"string"}},"existingCapabilities":{"type":"array","items":{"type":"string"}}}}},"remove":{"type":"array","items":{"type":"string"}}}},"maximumOutputTokens":12000,"temperature":0.2}}},"bind":[{"target":"modelRequest.interaction.messages[1].content","fromStep":"read-sources","path":"$.value.text"},{"target":"modelRequest.interaction.messages[2].content","fromStep":"read-sources","path":"$.value.capabilityIds"},{"target":"modelRequest.interaction.messages[3].content","fromStep":"read-sources","path":"$.value.obligations"},{"target":"modelRequest.interaction.messages[4].content","fromStep":"check-written","path":"$.value.censusJson"},{"target":"modelRequest.interaction.messages[5].content","fromStep":"gate-written","path":"$.value.feedback"}],"obligationIds":["O4"],"expect":{"path":"$.disposition","equals":"MODEL_RESPONSE_OBTAINED"}},{"stepId":"apply-correction","capabilityId":"sql-database-reader","historicalBasis":"probe 02d25ab9: patchIsJson 1 (30 areas); self-test e7694567 (remove, r